import type { Meta, StoryObj } from '@storybook/angular';
import { moduleMetadata, applicationConfig } from '@storybook/angular';
import { provideAnimations } from '@angular/platform-browser/animations';
import { MAT_DIALOG_DATA, MatDialog, MatDialogModule, MatDialogRef } from '@angular/material/dialog';
import { MatButtonModule } from '@angular/material/button';
import { Component, Inject } from '@angular/core';
import { DxConfirmComponent } from './dx-confirm.component';
import { DxButtonModule } from '../dx-button/dx-button.module';

// ──────────────────────────────────────────────────────────────────────────
// Shared payload shape — what gets passed via MAT_DIALOG_DATA
// ──────────────────────────────────────────────────────────────────────────

type ConfirmPayload = {
  header?: {
    title?: string;
    closeIcon?: boolean;
    icon?: { isShow: boolean; icon: string; color: string };
  };
  content?: { message?: string };
  actions?: {
    primary?: { title?: string };
    secondary?: { title?: string };
  };
};

const stubDialogRef = {
  close: () => {},
} as unknown as MatDialogRef<DxConfirmComponent>;

// ──────────────────────────────────────────────────────────────────────────
// Inline render — drops the component on the canvas inside a card-shaped
// host. This is the "design preview" mode: shows what the dialog body
// looks like without actually opening MatDialog.
// ──────────────────────────────────────────────────────────────────────────

const inlineRender = (data: ConfirmPayload) => ({
  moduleMetadata: {
    providers: [
      { provide: MAT_DIALOG_DATA, useValue: data },
      { provide: MatDialogRef,    useValue: stubDialogRef },
    ],
  },
  template: `
    <div style="max-width:420px; padding:16px; border:1px solid #e0e0e0; border-radius:12px; box-shadow:0 6px 20px rgba(0,0,0,0.08); background:#fff;">
      <dx-confirm></dx-confirm>
    </div>
  `,
});

// ──────────────────────────────────────────────────────────────────────────
// Launcher — opens the real MatDialog so click flow + close event are
// observable end-to-end.
// ──────────────────────────────────────────────────────────────────────────

@Component({
  selector: 'dx-confirm-launcher',
  template: `
    <div style="display:flex; flex-direction:column; gap:12px; align-items:flex-start;">
      <button mat-raised-button color="primary" (click)="open()">Open confirm dialog</button>
      <div *ngIf="lastResult !== null; else hint" style="font-family:monospace; font-size:12px; background:#f5f5f5; padding:10px 14px; border-radius:6px;">
        Last result: <strong>{{ lastResult }}</strong>
      </div>
      <ng-template #hint>
        <p style="margin:0; color:#666;">Click the button to open the dialog; the close payload (true / false) appears here.</p>
      </ng-template>
    </div>
  `,
})
export class DxConfirmLauncher {
  data: ConfirmPayload = {
    header: { title: 'Confirm action', closeIcon: true, icon: { isShow: true, icon: 'help_outline', color: '#1d6cc0' } },
    content: { message: 'Are you sure you want to continue?' },
    actions: { primary: { title: 'Confirm' }, secondary: { title: 'Cancel' } },
  };
  lastResult: boolean | null = null;

  constructor(@Inject(MatDialog) private readonly dialog: MatDialog) {}

  open(): void {
    const ref = this.dialog.open(DxConfirmComponent, { data: this.data, width: '420px' });
    ref.afterClosed().subscribe((result: boolean) => { this.lastResult = result === true; });
  }
}

const meta: Meta<DxConfirmComponent> = {
  title: 'Overlays/Confirm',
  component: DxConfirmComponent,
  decorators: [
    moduleMetadata({
      imports: [DxButtonModule, MatDialogModule, MatButtonModule],
      declarations: [DxConfirmLauncher],
    }),
    applicationConfig({ providers: [provideAnimations()] }),
  ],
  parameters: {
    docs: {
      description: {
        component:
          'Material-dialog body (`dx-confirm`) used as the standard confirmation prompt. ' +
          'The body reads `MAT_DIALOG_DATA: { header: { title, icon, closeIcon }, content: { message }, ' +
          'actions: { primary, secondary } }` and closes the `MatDialogRef` with `true` (primary) or ' +
          '`false` (secondary / close icon). Stories below render the component inline against a ' +
          'stub `MatDialogRef` for visual preview; the **Live dialog (launcher)** story opens the ' +
          'real `MatDialog` so the close-event flow is observable.',
      },
    },
  },
};

export default meta;
type Story = StoryObj<any>;

// ──────────────────────────────────────────────────────────────────────────
// Inline variants — design previews
// ──────────────────────────────────────────────────────────────────────────

export const Default: Story = {
  name: 'Default confirm',
  parameters: { docs: { description: { story: 'Standard question — info-blue icon, "Confirm" / "Cancel".' } } },
  render: () => inlineRender({
    header: { title: 'Confirm action', closeIcon: true, icon: { isShow: true, icon: 'help_outline', color: '#1d6cc0' } },
    content: { message: 'Are you sure you want to continue?' },
    actions: { primary: { title: 'Confirm' }, secondary: { title: 'Cancel' } },
  }),
};

export const Destructive: Story = {
  name: 'Destructive (delete)',
  parameters: { docs: { description: { story: 'Red icon + "Delete" CTA — confirms a destructive action.' } } },
  render: () => inlineRender({
    header: { title: 'Delete invoice?', closeIcon: true, icon: { isShow: true, icon: 'delete_outline', color: '#E74C3C' } },
    content: { message: 'INV-1234 will be permanently removed. This action cannot be undone.' },
    actions: { primary: { title: 'Delete' }, secondary: { title: 'Keep' } },
  }),
};

export const Warning: Story = {
  name: 'Warning',
  parameters: { docs: { description: { story: 'Amber icon — alerts the user to a risky but recoverable action.' } } },
  render: () => inlineRender({
    header: { title: 'Discard changes?', closeIcon: true, icon: { isShow: true, icon: 'warning_amber', color: '#F39C12' } },
    content: { message: 'You have unsaved edits. Leaving will discard them.' },
    actions: { primary: { title: 'Discard' }, secondary: { title: 'Stay' } },
  }),
};

export const Success: Story = {
  name: 'Success',
  parameters: { docs: { description: { story: 'Green icon — typically used to confirm completion of a multi-step flow.' } } },
  render: () => inlineRender({
    header: { title: 'Account created', closeIcon: false, icon: { isShow: true, icon: 'check_circle_outline', color: '#16A085' } },
    content: { message: 'Your workspace is ready. Continue to the dashboard?' },
    actions: { primary: { title: 'Open dashboard' }, secondary: { title: 'Later' } },
  }),
};

export const NoIcon: Story = {
  name: 'No icon',
  parameters: { docs: { description: { story: '`header.icon.isShow=false` (or omit `icon`) — text-only prompt.' } } },
  render: () => inlineRender({
    header: { title: 'Send invitation?', closeIcon: true },
    content: { message: 'An email will be sent to alex@example.com inviting them to your workspace.' },
    actions: { primary: { title: 'Send' }, secondary: { title: 'Cancel' } },
  }),
};

export const NoCloseIcon: Story = {
  name: 'No close icon (forced decision)',
  parameters: { docs: { description: { story: '`header.closeIcon=false` hides the × in the corner so the user must pick one of the two actions.' } } },
  render: () => inlineRender({
    header: { title: 'Accept terms?', closeIcon: false, icon: { isShow: true, icon: 'gavel', color: '#9B59B6' } },
    content: { message: 'You must accept the updated Terms of Service to continue using the app.' },
    actions: { primary: { title: 'I accept' }, secondary: { title: 'Decline' } },
  }),
};

export const LongMessage: Story = {
  name: 'Long message',
  parameters: { docs: { description: { story: 'Tests the body when the message wraps over multiple lines.' } } },
  render: () => inlineRender({
    header: { title: 'Switch billing plan?', closeIcon: true, icon: { isShow: true, icon: 'attach_money', color: '#3498DB' } },
    content: { message: 'Switching from Enterprise to Pro will reduce your monthly seat count to 25 and remove SSO. Pending exports will continue to completion. Custom dashboards configured before the switch will be retained but may be limited by the new feature set.' },
    actions: { primary: { title: 'Switch plan' }, secondary: { title: 'Keep current plan' } },
  }),
};

export const NoTitle: Story = {
  name: 'No title (message only)',
  parameters: { docs: { description: { story: 'Drop `header.title` for a quick yes/no prompt.' } } },
  render: () => inlineRender({
    content: { message: 'Mark this thread as resolved?' },
    actions: { primary: { title: 'Yes' }, secondary: { title: 'No' } },
  }),
};

// ──────────────────────────────────────────────────────────────────────────
// Live dialog launcher
// ──────────────────────────────────────────────────────────────────────────

export const LiveDialog: Story = {
  name: 'Live dialog (launcher)',
  parameters: { docs: { description: { story: 'Opens the real `MatDialog` so you can see the overlay backdrop, click "Confirm" / "Cancel" / ×, and observe the close payload (`true` / `false`).' } } },
  render: () => ({ template: `<dx-confirm-launcher></dx-confirm-launcher>` }),
};

import type { Meta, StoryObj } from '@storybook/angular';
import { moduleMetadata, applicationConfig } from '@storybook/angular';
import { provideAnimations } from '@angular/platform-browser/animations';
import { Component, Input } from '@angular/core';
import { DxDrawerComponent } from './drawer.component';
import { DxDrawerModule } from './drawer.module';
import { MatButtonModule } from '@angular/material/button';

// ──────────────────────────────────────────────────────────────────────────
// Launcher — `<dx-drawer>` is an overlay container. Toggling `[nzVisible]`
// from outside is the standard way to open / close it. Inline rendering
// would leave it permanently mounted; the launcher exposes a button so the
// open/close lifecycle is observable.
// ──────────────────────────────────────────────────────────────────────────

@Component({
  selector: 'dx-drawer-launcher',
  template: `
    <div style="display:flex; flex-direction:column; gap:12px; align-items:flex-start;">
      <button mat-raised-button color="primary" (click)="visible = true">{{ openLabel }}</button>
      <p style="margin:0; color:#666;">{{ helper }}</p>

      <dx-drawer
        [nzVisible]="visible"
        [dxTitle]="title"
        [dxExtra]="extra"
        [dxFooter]="footer"
        [dxPlacement]="placement"
        [dxSize]="size"
        [dxWidth]="width"
        [dxHeight]="height"
        [dxMask]="mask"
        [dxMaskClosable]="maskClosable"
        [dxClosable]="closable"
        [dxKeyboard]="keyboard"
        [dxNoAnimation]="noAnimation"
        [dxZIndex]="zIndex"
        [dxOffsetX]="offsetX"
        [dxOffsetY]="offsetY"
        [dxWrapClassName]="wrapClassName"
        (dxOnClose)="visible = false"
        (dxVisibleChange)="onVisibleChange($event)">
        <dx-drawer-content>
          <div style="padding:16px; line-height:1.6;">
            <p style="margin-top:0;"><strong>{{ title || 'Drawer body' }}</strong></p>
            <p>{{ body }}</p>
            <p style="margin:0;">Place anything inside <code>&lt;dx-drawer-content&gt;</code> — forms, tables, summaries.</p>
          </div>
        </dx-drawer-content>
      </dx-drawer>
    </div>
  `,
})
export class DxDrawerLauncher {
  @Input() openLabel = 'Open drawer';
  @Input() helper = 'Click to slide the drawer in. Click the backdrop, the × icon, or press Esc to close.';
  @Input() title = 'Drawer title';
  @Input() extra = '';
  @Input() footer = '';
  @Input() placement: 'left' | 'right' | 'top' | 'bottom' = 'right';
  @Input() size: 'default' | 'large' = 'default';
  @Input() width: number | string = '';
  @Input() height: number | string = '';
  @Input() mask = true;
  @Input() maskClosable = true;
  @Input() closable = true;
  @Input() keyboard = true;
  @Input() noAnimation = false;
  @Input() zIndex = 1000;
  @Input() offsetX = 0;
  @Input() offsetY = 0;
  @Input() wrapClassName = '';
  @Input() body = 'Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.';

  visible = false;

  onVisibleChange(v: boolean): void {
    this.visible = v;
  }
}

const meta: Meta<DxDrawerLauncher> = {
  title: 'Overlays/Drawer',
  component: DxDrawerLauncher,
  decorators: [
    moduleMetadata({
      imports: [DxDrawerModule, MatButtonModule],
      declarations: [DxDrawerLauncher],
    }),
    applicationConfig({ providers: [provideAnimations()] }),
  ],
  parameters: {
    docs: {
      description: {
        component:
          'Slide-in overlay container (`<dx-drawer>`). Open / close via the `[nzVisible]` two-way ' +
          'binding (or via `DxDrawerService.create()` when you need a programmatic API). Configure ' +
          'placement (`left` / `right` / `top` / `bottom`), size (`default` / `large` or explicit ' +
          '`[dxWidth]` / `[dxHeight]`), backdrop behavior (`[dxMask]`, `[dxMaskClosable]`, ' +
          '`[dxKeyboard]`), title / extra / footer slots, and z-index / offsets. The drawer body ' +
          'goes inside `<dx-drawer-content>`. The stories below all wrap the drawer in a small ' +
          'launcher button so the open / close cycle is observable.',
      },
    },
  },
  argTypes: {
    placement: { control: { type: 'inline-radio' }, options: ['left', 'right', 'top', 'bottom'], description: 'Slide-in edge.' },
    size:      { control: { type: 'inline-radio' }, options: ['default', 'large'], description: '`default` = 256px, `large` = 736px on horizontal placements (vice versa for vertical).' },
    width:     { control: 'text', description: 'Explicit `dxWidth` override (e.g. `"420px"`, `"50%"`). Wins over `dxSize`.' },
    height:    { control: 'text', description: 'Explicit `dxHeight` override.' },
    mask:        { control: 'boolean', description: 'Show the dimmed backdrop behind the drawer.' },
    maskClosable:{ control: 'boolean', description: 'Click backdrop closes the drawer.' },
    closable:    { control: 'boolean', description: 'Show the × icon in the header.' },
    keyboard:    { control: 'boolean', description: 'Esc key closes the drawer.' },
    noAnimation: { control: 'boolean', description: 'Skip the slide animation.' },
    zIndex:      { control: 'number', description: 'CSS z-index (default 1000).' },
    offsetX:     { control: 'number', description: 'Horizontal offset from the edge (left/right placement).' },
    offsetY:     { control: 'number', description: 'Vertical offset from the edge (top/bottom placement).' },
    title:       { control: 'text' },
    extra:       { control: 'text', description: 'Right-aligned slot in the header (extra action / label).' },
    footer:      { control: 'text', description: 'Fixed footer slot.' },
    body:        { control: 'text', description: 'Demo body text rendered inside `<dx-drawer-content>`.' },
    wrapClassName:{ control: 'text', description: 'Extra class applied to the drawer wrapper.' },
  },
};

export default meta;
type Story = StoryObj<DxDrawerLauncher>;

// ──────────────────────────────────────────────────────────────────────────
// Stories
// ──────────────────────────────────────────────────────────────────────────

export const Default: Story = {
  name: 'Right (default)',
  args: { placement: 'right', size: 'default', title: 'Settings' },
  parameters: { docs: { description: { story: 'Standard right-side drawer at the default 256px size.' } } },
  render: (args) => ({ props: args }),
};

export const LeftPlacement: Story = {
  name: 'Left placement',
  args: { placement: 'left', title: 'Navigation' },
  parameters: { docs: { description: { story: '`dxPlacement="left"` — slides in from the left edge (common for nav drawers).' } } },
  render: (args) => ({ props: args }),
};

export const TopPlacement: Story = {
  name: 'Top placement',
  args: { placement: 'top', title: 'Notifications' },
  parameters: { docs: { description: { story: '`dxPlacement="top"` — drops in from the top edge.' } } },
  render: (args) => ({ props: args }),
};

export const BottomPlacement: Story = {
  name: 'Bottom placement',
  args: { placement: 'bottom', title: 'Quick actions' },
  parameters: { docs: { description: { story: '`dxPlacement="bottom"` — slides up from the bottom edge (good for mobile-style sheets).' } } },
  render: (args) => ({ props: args }),
};

export const LargeSize: Story = {
  name: 'Large size',
  args: { size: 'large', title: 'User profile' },
  parameters: { docs: { description: { story: '`dxSize="large"` widens the drawer to 736px (or 50% on small viewports).' } } },
  render: (args) => ({ props: args }),
};

export const CustomWidth: Story = {
  name: 'Custom width',
  args: { width: '50%', title: 'Filters', body: 'Wide drawer — useful when the body hosts a multi-column form.' },
  parameters: { docs: { description: { story: '`[dxWidth]` overrides `dxSize`. Accepts any CSS width — number (px), percent, or named unit.' } } },
  render: (args) => ({ props: args }),
};

export const WithExtraAndFooter: Story = {
  name: 'Title + extra + footer slots',
  args: {
    title: 'Edit record',
    extra: 'Last saved · 2 min ago',
    footer: 'Cancel  |  Save',
    body: 'The footer stays pinned to the bottom of the drawer; the extra slot sits in the top-right next to the close button.',
  },
  parameters: { docs: { description: { story: 'All three text slots — `[dxTitle]`, `[dxExtra]`, `[dxFooter]` — populated.' } } },
  render: (args) => ({ props: args }),
};

export const NoMask: Story = {
  name: 'No backdrop',
  args: { mask: false, title: 'Inline drawer', body: 'Click outside is still allowed — the rest of the page remains interactive.' },
  parameters: { docs: { description: { story: '`[dxMask]="false"` removes the dimmed backdrop. Useful when the drawer should overlay without blocking surrounding interactions.' } } },
  render: (args) => ({ props: args }),
};

export const NotClosable: Story = {
  name: 'Not closable (no ×, no Esc, no backdrop click)',
  args: { closable: false, keyboard: false, maskClosable: false, title: 'Wizard step 2', body: 'Forced flow — user must complete the action via the footer.' },
  parameters: { docs: { description: { story: '`[dxClosable]="false"` + `[dxKeyboard]="false"` + `[dxMaskClosable]="false"` together force the user through an action inside the drawer.' } } },
  render: (args) => ({ props: args }),
};

export const NoAnimation: Story = {
  name: 'No animation',
  args: { noAnimation: true, title: 'Quick open' },
  parameters: { docs: { description: { story: '`[dxNoAnimation]="true"` — the drawer appears / disappears without the slide transition. Use sparingly; helps with reduced-motion preferences.' } } },
  render: (args) => ({ props: args }),
};

export const Offset: Story = {
  name: 'Offset from edge',
  args: { offsetX: 32, title: 'Nudged drawer', body: '`dxOffsetX` shifts the drawer 32px away from the right edge.' },
  parameters: { docs: { description: { story: '`[dxOffsetX]` / `[dxOffsetY]` push the drawer away from its anchor edge — useful when a persistent header / sidenav already occupies that space.' } } },
  render: (args) => ({ props: args }),
};

import type { Meta, StoryObj } from '@storybook/angular';
import { moduleMetadata, applicationConfig } from '@storybook/angular';
import { provideAnimations } from '@angular/platform-browser/animations';
import { MatDialog, MatDialogModule, MatDialogRef } from '@angular/material/dialog';
import { MatButtonModule } from '@angular/material/button';
import { Component, Inject } from '@angular/core';
import { of, type Observable } from 'rxjs';
import { DxIconSelectionPopupComponent } from './dx-icon-selection-popup.component';
import { DxIconSelectionPopupModule } from './dx-icon-selection-popup.module';
import { IconService } from './service/icon.service';
import type { IconConfig } from './model/icon.interface';
import type { PaginationRequest } from '../dx-config-table';

// ──────────────────────────────────────────────────────────────────────────
// Stub IconService — the dialog body fetches two endpoints on mount
// (`iconCategoryURL`, `iconListURL`). In Storybook we substitute a stub that
// returns canned categories + icons so the popup actually populates.
// ──────────────────────────────────────────────────────────────────────────

const CATEGORIES = [
  { categoryKey: 'navigation', categoryName: 'Navigation' },
  { categoryKey: 'action',     categoryName: 'Actions' },
  { categoryKey: 'social',     categoryName: 'Social' },
  { categoryKey: 'communication', categoryName: 'Communication' },
];

const ICON_NAMES: Record<string, string[]> = {
  navigation:    ['home', 'menu', 'arrow_back', 'arrow_forward', 'chevron_left', 'chevron_right', 'expand_more', 'expand_less'],
  action:        ['edit', 'delete', 'save', 'add', 'remove', 'check', 'close', 'refresh', 'download', 'upload'],
  social:        ['person', 'group', 'share', 'thumb_up', 'thumb_down', 'star', 'favorite'],
  communication: ['email', 'call', 'chat', 'sms', 'forum', 'inbox', 'send'],
};

function buildIconRows() {
  let id = 1;
  return Object.entries(ICON_NAMES).flatMap(([categoryKey, names]) => {
    const category = CATEGORIES.find(c => c.categoryKey === categoryKey)!;
    return names.map(name => ({
      pkId: id++,
      iconKey: name,
      iconName: name,
      categoryKey,
      categoryName: category.categoryName,
      tags: name,
      sizesPx: 24,
    }));
  });
}

const ALL_ICONS = buildIconRows();

class StubIconService {
  fetchIconCategory(_config?: IconConfig): Observable<any> {
    return of(CATEGORIES);
  }

  fetchIconList(request: PaginationRequest, _config?: IconConfig): Observable<any> {
    // Honor the search filter the component composes
    // (`categoryKey:eq:<key>,tags:lk:<query>`)
    let rows = ALL_ICONS.slice();
    const search = request?.search ?? '';
    const tokens = search ? search.split(',') : [];
    for (const token of tokens) {
      const [field, operator, value] = token.split(':');
      if (!value) continue;
      if (field === 'categoryKey' && operator === 'eq') {
        rows = rows.filter(r => r.categoryKey === value);
      } else if (field === 'tags' && operator === 'lk') {
        const needle = value.toLowerCase();
        rows = rows.filter(r => (r.tags ?? '').toLowerCase().includes(needle));
      }
    }
    const pageNo   = request?.pageNo ?? 0;
    const pageSize = request?.pageSize ?? 50;
    const start = pageNo * pageSize;
    const slice = rows.slice(start, start + pageSize);
    return of({ content: slice, totalElements: rows.length, size: pageSize, number: pageNo });
  }
}

const SAMPLE_CONFIG: IconConfig = {
  iconCategoryURL: '/api/icons/categories',
  iconListURL:     '/api/icons/list',
};

// ──────────────────────────────────────────────────────────────────────────
// Inline render — the popup is a Material dialog body. Stub MatDialogRef so
// rendering directly doesn't crash; the user sees the visual chrome without
// the modal animation.
// ──────────────────────────────────────────────────────────────────────────

const stubDialogRef = {
  close: (_v?: unknown) => {},
} as unknown as MatDialogRef<DxIconSelectionPopupComponent>;

const inlineRender = (iconConfig: IconConfig = SAMPLE_CONFIG) => ({
  moduleMetadata: {
    providers: [
      { provide: MatDialogRef, useValue: stubDialogRef },
      { provide: IconService,  useClass: StubIconService },
    ],
  },
  props: { iconConfig },
  template: `
    <div style="max-width:720px; padding:0; border:1px solid #e0e0e0; border-radius:12px; box-shadow:0 6px 20px rgba(0,0,0,0.08); background:#fff; overflow:hidden;">
      <dx-icon-selection-popup [iconConfig]="iconConfig"></dx-icon-selection-popup>
    </div>
  `,
});

// ──────────────────────────────────────────────────────────────────────────
// Launcher — opens the real MatDialog with the stubbed service so the close
// payload is observable.
// ──────────────────────────────────────────────────────────────────────────

@Component({
  selector: 'dx-icon-selection-launcher',
  template: `
    <div style="display:flex; flex-direction:column; gap:12px; align-items:flex-start;">
      <button mat-raised-button color="primary" (click)="open()">Open icon picker</button>
      <div *ngIf="picked !== null; else hint"
           style="font-family:monospace; font-size:12px; background:#f5f5f5; padding:10px 14px; border-radius:6px; display:flex; align-items:center; gap:8px;">
        <span>Picked:</span>
        <span class="material-icons" style="vertical-align:middle;">{{ picked }}</span>
        <strong>{{ picked }}</strong>
      </div>
      <ng-template #hint>
        <p style="margin:0; color:#666;">Click the button to open the icon picker. The chosen icon name appears here.</p>
      </ng-template>
    </div>
  `,
})
export class DxIconSelectionLauncher {
  picked: string | null = null;
  constructor(@Inject(MatDialog) private readonly dialog: MatDialog) {}

  open(): void {
    const ref = this.dialog.open(DxIconSelectionPopupComponent, { width: '720px' });
    ref.componentInstance.iconConfig = SAMPLE_CONFIG;
    ref.afterClosed().subscribe((iconName: string | undefined) => {
      if (iconName) this.picked = iconName;
    });
  }
}

const meta: Meta<DxIconSelectionPopupComponent> = {
  title: 'Overlays/Icon Selection Popup',
  component: DxIconSelectionPopupComponent,
  decorators: [
    moduleMetadata({
      imports: [DxIconSelectionPopupModule, MatDialogModule, MatButtonModule],
      declarations: [DxIconSelectionLauncher],
    }),
    applicationConfig({ providers: [provideAnimations()] }),
  ],
  parameters: {
    docs: {
      description: {
        component:
          'Material-dialog body that lets users pick an icon from a server-backed catalog. ' +
          'On mount it calls `IconService.fetchIconCategory(iconConfig)` to populate the category ' +
          'chips, then `fetchIconList(paginationRequest, iconConfig)` for the icon grid. The search ' +
