          'with the chosen `iconName`. The stories below stub `IconService` with an in-memory ' +
          'catalog so the popup renders without a backend.',
      },
    },
  },
  argTypes: {
    iconConfig: { control: 'object', description: '`IconConfig` — `{ iconCategoryURL, iconListURL }`.' },
  },
};

export default meta;
